#!/usr/bin/env python3
from pathlib import Path
import base64, json, re, zlib

ROOT = Path(__file__).resolve().parents[1]
BOOK = ROOT / "app/src/main/assets/data/book.json"

payload = """"""
overlay = json.loads(zlib.decompress(base64.b64decode(payload)).decode("utf-8"))
rows = json.loads(BOOK.read_text(encoding="utf-8"))

if len(rows) != 37:
    raise SystemExit(f"Phase-4 expected 37 lessons, found {len(rows)}")
ids = {x.get("id") for x in rows}
if ids != set(overlay):
    raise SystemExit("Phase-4 overlay does not exactly cover the 37 lesson IDs")

for row in rows:
    patch = overlay[row["id"]]
    row["ta_t"] = patch["ta_t"]
    row["ta"] = patch["ta"]
    if "en" in patch:
        row["en"] = patch["en"]

BOOK.write_text(json.dumps(rows, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")

combined = "\n".join(x["ta_t"] + "\n" + x["ta"] for x in rows)
banned = [
    "TNAU", "Agritech", "இப்பயன்பாடு", "சமையல் குறிப்பு", "பாடத்திட்ட முதல் உணவு",
    "வணிக இயல்பாக", "உயிரியையோ", "அகணியம்", "அருகிய நிலை", "குப்பி",
    "கர்ப்பகாலம்", "கர்ப்பப்", "நீர்க்கட்டிகள்", "புழைமூச்சு", "தள உறுப்பு",
    "இருப்பு என்பது", "அத்துமீறல் இடர்", "அனுமதிச் சொல்லில்லாமல்", "மென்நீர்",
    "முதல் பதிப்பு"
]
found = [term for term in banned if term.lower() in combined.lower()]
if found:
    raise SystemExit("Phase-4 Tamil lesson wording gate failed: " + ", ".join(found))

for row in rows:
    if not re.search(r"[\u0B80-\u0BFF]", row["ta_t"] + row["ta"]):
        raise SystemExit("Tamil content missing in lesson " + row["id"])

print("PHASE-4 TAMIL LESSON POLISH: PASS — 37 / 37 lessons covered")
